<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>SALTWATCH — Tactical FPS</title>
<style>
  :root {
    --lamp: #ffb347; --lamp-dim: #b97f22; --teal: #2fd6c0; --rust: #c2491e;
    --ink: #eef4f2; --muted: #9db4ae; --sand: #d9c9a8; --panel: rgba(10, 18, 24, 0.85);
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-read: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; overflow: hidden; background: #0a1218; color: var(--ink); font-family: var(--font-ui); }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }
  #crosshair { position: fixed; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%, -50%); --gap: 6px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; }
  #crosshair i:nth-child(1) { left: 14px; top: calc(15px - var(--gap) - 8px); width: 2px; height: 8px; }
  #crosshair i:nth-child(2) { left: 14px; top: calc(15px + var(--gap)); width: 2px; height: 8px; }
  #crosshair i:nth-child(3) { top: 14px; left: calc(15px - var(--gap) - 8px); height: 2px; width: 8px; }
  #crosshair i:nth-child(4) { top: 14px; left: calc(15px + var(--gap)); height: 2px; width: 8px; }
  #crosshair b { position: absolute; left: 14px; top: 14px; width: 2px; height: 2px; background: var(--lamp); }
  #hitmarker { position: fixed; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; }
  #hitmarker.on { opacity: 1; } #hitmarker.kill i { background: #ff4d2e; }
  #hitmarker i { position: absolute; background: var(--sand); }
  #hitmarker i:nth-child(1) { left: 14px; top: 0; width: 2px; height: 9px; }
  #hitmarker i:nth-child(2) { left: 14px; bottom: 0; width: 2px; height: 9px; }
  #hitmarker i:nth-child(3) { top: 14px; left: 0; height: 2px; width: 9px; }
  #hitmarker i:nth-child(4) { top: 14px; right: 0; height: 2px; width: 9px; }
  #dmg-vignette { position: fixed; inset: 0; opacity: 0; transition: opacity 120ms; background: radial-gradient(ellipse at center, transparent 55%, rgba(200, 30, 10, 0.55) 100%); }
  #dmg-vignette.on { opacity: 1; }
  #dmg-dir { position: fixed; left: 50%; top: 50%; width: 120px; height: 120px; margin: -60px 0 0 -60px; opacity: 0; }
  #dmg-dir.on { opacity: 1; }
  #dmg-dir::before { content: ''; position: absolute; left: 50%; top: 0; width: 26px; height: 10px; margin-left: -13px; background: #ff4d2e; border-radius: 4px; }
  #flash-overlay { position: fixed; inset: 0; background: #fff; opacity: 0; }
  .bl { position: fixed; left: 28px; bottom: 22px; font-family: var(--font-read); }
  #hud-healthbar-wrap { width: 210px; height: 8px; background: rgba(0,0,0,.5); border: 1px solid rgba(255,255,255,.25); margin-bottom: 6px; }
