  /* Stance badge: makes crouch visible on screen — JONGKOK lowers the eye and tightens spread. */
  #hud-stance { position: fixed; bottom: 132px; left: 50%; transform: translateX(-50%); font-family: var(--font-read); font-size: 12px; letter-spacing: .14em; color: var(--teal); background: var(--panel); padding: 4px 10px; border: 1px solid var(--teal); }
  #hud-stance[hidden] { display: none; }
