  #plant-label { font-size: 13px; letter-spacing: .12em; color: var(--lamp); margin-top: 6px; }
  #round-banner { position: fixed; left: 50%; top: 30%; transform: translateX(-50%); text-align: center; }
  #banner-title { font-size: 44px; letter-spacing: .06em; margin: 0; text-shadow: 0 2px 12px rgba(0,0,0,.7); }
  #banner-title.win { color: var(--teal); } #banner-title.lose { color: #ff4d2e; }
  #banner-sub { font-size: 16px; color: var(--ink); background: var(--panel); display: inline-block; padding: 6px 14px; margin-top: 8px; }
  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: rgba(6, 12, 16, 0.72); }
  .overlay[hidden], #buy-menu[hidden], #round-banner[hidden], #plant-ring[hidden], #bomb-timer[hidden] { display: none; }
  .panel { width: min(480px, 100%); padding: 32px; background: var(--panel); border: 1px solid var(--lamp-dim); border-radius: 6px; }
  .panel h1 { margin: 0 0 4px; font-size: 40px; letter-spacing: .08em; color: var(--lamp); }
  .panel h1 span { color: var(--ink); }
  .panel p { margin: 0 0 20px; font-size: 15px; line-height: 1.55; color: var(--muted); }
  #play { font: inherit; font-weight: 600; padding: 12px 20px; border: 1px solid var(--lamp); border-radius: 6px; background: var(--lamp); color: #1c1205; cursor: pointer; }
  #play:hover { background: var(--sand); }
  .keys { margin: 22px 0 0; padding: 0; list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 7px; font-size: 13px; color: var(--muted); }
  .keys kbd { padding: 2px 6px; border: 1px solid rgba(255,255,255,.3); border-radius: 4px; font-family: var(--font-read); font-size: 12px; color: var(--ink); }
  #buy-menu { position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(560px, 92vw); background: var(--panel); border: 1px solid var(--lamp); border-radius: 6px; padding: 20px; pointer-events: auto; }
  #buy-menu h2 { margin: 0 0 4px; font-size: 20px; color: var(--lamp); }
  #buy-money { font-family: var(--font-read); color: var(--sand); margin-bottom: 12px; }
  #buy-list { display: grid; gap: 8px; }
  .buy-item { display: flex; justify-content: space-between; gap: 12px; align-items: center; font: inherit; text-align: left; padding: 10px 12px; background: rgba(255,255,255,.06); color: var(--ink); border: 1px solid rgba(255,255,255,.18); border-radius: 4px; cursor: pointer; }
  .buy-item:hover { border-color: var(--lamp); background: rgba(255,179,71,.15); }
  .buy-item span { color: var(--muted); font-size: 12px; } .buy-item em { font-style: normal; color: var(--sand); font-family: var(--font-read); }
</style>
</head>
