      const all = bots.list.concat([{ isPlayer: true, pos: player.pos, alive: player.alive, team: 'tide', hp: player.hp }]);
      for (const e of all) {
        if (!e.alive) continue;
        const dx = e.pos.x - p.x, dz = e.pos.z - p.z;
        const dy = (e.pos.y + 1) - p.y;
        const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
